CREATE TABLE products (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(150) NOT NULL, category VARCHAR(20) NOT NULL, description TEXT, base_price_kzt BIGINT NOT NULL CHECK (base_price_kzt >= 0), image_url TEXT, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE product_variants (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id BIGINT NOT NULL REFERENCES products(id), sku VARCHAR(60) NOT NULL UNIQUE, size VARCHAR(10) NOT NULL, color VARCHAR(40) NOT NULL, extra_price_kzt BIGINT NOT NULL DEFAULT 0 CHECK (extra_price_kzt >= 0), stock_quantity INTEGER NOT NULL DEFAULT 0 CHECK (stock_quantity >= 0), active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE INDEX idx_product_variants_product ON product_variants(product_id);
